/**
 * One run.
 */
public interface AgentRunInterface {

    /**
     * Files the run created or changed in its working directory.
     */
    suspend fun `artifacts`(): List<AgentArtifact>

    /**
     * Events after `cursor` (0: from the start), at most `max`.
     */
    suspend fun `events`(`cursor`: kotlin.ULong, `max`: kotlin.UInt?): AgentEventPage

    fun `harness`(): kotlin.String

    /**
     * Cancels the turn in flight; the session stays open.
     */
    suspend fun `interrupt`(): AgentRunInfo

    /**
     * Stops the run and deletes its directory (secrets included).
     */
    suspend fun `remove`()

    /**
     * The last turn's outcome.
     */
    suspend fun `result`(): AgentRunResult

    fun `runId`(): kotlin.String

    /**
     * A follow-up in the same session (queued while a turn runs).
     */
    suspend fun `send`(`text`: kotlin.String, `files`: List<AgentFile>?): AgentRunInfo

    suspend fun `status`(): AgentRunInfo

    /**
     * Stops the run and verifies its process is gone.
     */
    suspend fun `stop`(): AgentRunInfo

    /**
     * Waits until no turn is running (at most `timeout_ms`), then returns
     * the result.
     */
    suspend fun `wait`(`timeoutMs`: kotlin.ULong?): AgentRunResult

    companion object
}

