/**
 * Sign-in and the shared session.
 */
public interface AuthInterface {

    /**
     * A valid access token (refreshed when it expires within a minute, or
     * when `force`). `Unauthenticated` when not signed in.
     */
    suspend fun `accessToken`(`force`: kotlin.Boolean): kotlin.String

    /**
     * Starts a sign-in. `flow`: `auto` (default: browser, else device
     * code), `browser` or `device`.
     */
    suspend fun `beginLogin`(`flow`: kotlin.String?): LoginAttempt

    /**
     * Revokes (best effort) and removes the session. Returns whether one
     * existed.
     */
    suspend fun `logout`(): kotlin.Boolean

    /**
     * The stored session (no network).
     */
    fun `status`(): AuthStatus

    /**
     * This device on `relay_url` (`None` = `CUA_RELAY_URL`, else
     * `https://relay.cua.ai`) as the signed-in account, shown as `name`
     * (default: the host name).
     */
    fun `devices`(`relayUrl`: kotlin.String?, `name`: kotlin.String?): Devices

    companion object
}

