    @Suppress("ASSIGNED_BUT_NEVER_ACCESSED_VARIABLE")
    override suspend fun `approve`(`code`: kotlin.String?, `deviceId`: kotlin.String?) : RelayDevice {
        return uniffiRustCallAsync(
        callWithHandle { uniffiHandle ->
            UniffiLib.uniffi_cua_sdk_fn_method_devices_approve(
