    fun `localAddr`(): kotlin.String?

    /**
     * URL to use (loopback URL, or the Fleet gateway URL).
     */
    fun `url`(): kotlin.String?

    companion object
}

/**
 * An active port forward. Closed on `close()` or when dropped.
 */
open class PortForward: Disposable, AutoCloseable, PortForwardInterface
{

