     */override fun `guestPort`(): kotlin.UShort {
            return FfiConverterUShort.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_cua_sdk_fn_method_portforward_guest_port(
        it,
        _status)
}
    }
    )
    }



    /**
     * Loopback `host:port` accepting connections (local/direct).
     */override fun `localAddr`(): kotlin.String? {
            return FfiConverterOptionalString.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_cua_sdk_fn_method_portforward_local_addr(
        it,
        _status)
}
    }
    )
    }



    /**
     * URL to use (loopback URL, or the Fleet gateway URL).
     */override fun `url`(): kotlin.String? {
            return FfiConverterOptionalString.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
