/**
 * A live Space media session (see [`Space::stream_session`]).
 */
public interface SpaceStreamSessionInterface {

    /**
     * Closes the socket and the media session. Returns the final counters.
     */
    suspend fun `closeStream`(): SpaceStreamStats

    /**
     * Negotiated codec.
     */
    fun `codec`(): kotlin.String

    /**
     * Whether the socket is still open.
     */
    fun `isOpen`(): kotlin.Boolean

    /**
     * Media session id.
     */
    fun `mediaSessionId`(): kotlin.String

    /**
     * Asks the encoder for a keyframe.
     */
    fun `requestKeyframe`()

    /**
     * Sends a raw JSON control message (for example input events).
     */
    fun `sendText`(`json`: kotlin.String)

    /**
     * Delivery counters (zeros once closed).
     */
    fun `stats`(): SpaceStreamStats

    companion object
}

