                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_cua_sdk_fn_free_spacestreamsession(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_cua_sdk_fn_clone_spacestreamsession(handle, status)
        }
    }


    /**
