    @Suppress("ASSIGNED_BUT_NEVER_ACCESSED_VARIABLE")
    override suspend fun `closeStream`() : SpaceStreamStats {
        return uniffiRustCallAsync(
        callWithHandle { uniffiHandle ->
            UniffiLib.uniffi_cua_sdk_fn_method_spacestreamsession_close(
                uniffiHandle,

            )
        },
        { future, callback, continuation -> UniffiLib.ffi_cua_sdk_rust_future_poll_rust_buffer(future, callback, continuation) },
        { future, continuation -> UniffiLib.ffi_cua_sdk_rust_future_complete_rust_buffer(future, continuation) },
        { future -> UniffiLib.ffi_cua_sdk_rust_future_free_rust_buffer(future) },
        // lift function
        { FfiConverterTypeSpaceStreamStats.lift(it) },
        // Error FFI converter
        CuaException.ErrorHandler,
    )
    }


    /**
     * Negotiated codec.
     */override fun `codec`(): kotlin.String {
            return FfiConverterString.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_cua_sdk_fn_method_spacestreamsession_codec(
        it,
        _status)
}
    }
    )
    }



    /**
