            return FfiConverterBoolean.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_cua_sdk_fn_method_spacestreamsession_is_open(
        it,
        _status)
}
    }
    )
    }



    /**
