     */override fun `mediaSessionId`(): kotlin.String {
            return FfiConverterString.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_cua_sdk_fn_method_spacestreamsession_media_session_id(
        it,
        _status)
}
    }
    )
    }



    /**
     * Asks the encoder for a keyframe.
     */
    @Throws(CuaException::class)override fun `requestKeyframe`()
        =
    callWithHandle {
    uniffiRustCallWithError(CuaException) { _status ->
    UniffiLib.uniffi_cua_sdk_fn_method_spacestreamsession_request_keyframe(
        it,
        _status)
}
    }




    /**
