     */
    @Throws(CuaException::class)override fun `sendText`(`json`: kotlin.String)
        =
    callWithHandle {
    uniffiRustCallWithError(CuaException) { _status ->
    UniffiLib.uniffi_cua_sdk_fn_method_spacestreamsession_send_text(
        it,
