/**
 * @suppress
 */
public object FfiConverterTypeImageLayer : FfiConverterRustBuffer<ImageLayer>{
    override fun read(buf: ByteBuffer): ImageLayer {
        return when(buf.getInt()) {
            1 -> ImageLayer.AptInstall(
                FfiConverterSequenceString.read(buf),
                )
            2 -> ImageLayer.PipInstall(
                FfiConverterSequenceString.read(buf),
                )
            3 -> ImageLayer.UvInstall(
                FfiConverterSequenceString.read(buf),
                )
            4 -> ImageLayer.Run(
                FfiConverterString.read(buf),
                )
            5 -> ImageLayer.AppInstall(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: ImageLayer) = when(value) {
        is ImageLayer.AptInstall -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceString.allocationSize(value.`packages`)
            )
        }
        is ImageLayer.PipInstall -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceString.allocationSize(value.`packages`)
            )
        }
        is ImageLayer.UvInstall -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceString.allocationSize(value.`packages`)
            )
        }
        is ImageLayer.Run -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`command`)
            )
        }
        is ImageLayer.AppInstall -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`appId`)
            )
        }
    }

    override fun write(value: ImageLayer, buf: ByteBuffer) {
        when(value) {
            is ImageLayer.AptInstall -> {
                buf.putInt(1)
                FfiConverterSequenceString.write(value.`packages`, buf)
                Unit
            }
            is ImageLayer.PipInstall -> {
                buf.putInt(2)
                FfiConverterSequenceString.write(value.`packages`, buf)
                Unit
            }
            is ImageLayer.UvInstall -> {
                buf.putInt(3)
                FfiConverterSequenceString.write(value.`packages`, buf)
                Unit
            }
            is ImageLayer.Run -> {
                buf.putInt(4)
                FfiConverterString.write(value.`command`, buf)
                Unit
            }
            is ImageLayer.AppInstall -> {
                buf.putInt(5)
                FfiConverterString.write(value.`appId`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





