    override fun read(buf: ByteBuffer): ReplayMode {
        return when(buf.getInt()) {
            1 -> ReplayMode.None
            2 -> ReplayMode.All
            3 -> ReplayMode.LastBytes(
                FfiConverterULong.read(buf),
                )
            4 -> ReplayMode.FromOffset(
                FfiConverterULong.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: ReplayMode) = when(value) {
        is ReplayMode.None -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is ReplayMode.All -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is ReplayMode.LastBytes -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`n`)
            )
        }
        is ReplayMode.FromOffset -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`offset`)
            )
        }
    }

    override fun write(value: ReplayMode, buf: ByteBuffer) {
        when(value) {
            is ReplayMode.None -> {
                buf.putInt(1)
                Unit
            }
            is ReplayMode.All -> {
                buf.putInt(2)
                Unit
            }
            is ReplayMode.LastBytes -> {
                buf.putInt(3)
                FfiConverterULong.write(value.`n`, buf)
                Unit
            }
            is ReplayMode.FromOffset -> {
                buf.putInt(4)
                FfiConverterULong.write(value.`offset`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





/**
 * Status of one local runtime component.
 */

enum class RuntimeCheckStatus {

    /**
     * Present and usable.
     */
    OK,
    /**
     * Missing; `setup` can provision it.
     */
    INSTALLABLE,
    /**
     * Missing or broken; needs user action.
     */
    ERROR,
    /**
     * Not used on this host.
     */
    NOT_APPLICABLE,
    /**
     * Not reported.
     */
    UNKNOWN;




    companion object
}


