/**
 * @suppress
 */
public object FfiConverterMapStringUShort: FfiConverterRustBuffer<Map<kotlin.String, kotlin.UShort>> {
    override fun read(buf: ByteBuffer): Map<kotlin.String, kotlin.UShort> {
        val len = buf.getInt()
        return buildMap<kotlin.String, kotlin.UShort>(len) {
            repeat(len) {
                val k = FfiConverterString.read(buf)
                val v = FfiConverterUShort.read(buf)
                this[k] = v
            }
